'use strict';
const $=id=>document.getElementById(id);
const OPS={add:['＋','たしざん'],sub:['−','ひきざん'],mul:['×','かけざん'],div:['÷','わりざん']};
const LEVELS=['かんたん','ふつう','むずかしい'];
const BANK={
add:[[[12,6],[23,14],[41,25],[32,17]],[[27,15],[46,28],[58,17],[36,49]],[[268,157],[476,285],[638,194],[759,168]]],
sub:[[[18,5],[47,23],[65,31],[39,16]],[[52,28],[73,46],[61,35],[84,57]],[[302,178],[500,263],[704,386],[603,257]]],
mul:[[[2,3],[4,2],[3,5],[5,5]],[[23,4],[36,3],[47,6],[58,7]],[[23,14],[36,25],[47,32],[68,24]]],
div:[[[12,3],[20,4],[18,2],[24,6]],[[72,3],[84,4],[96,6],[65,5]],[[83,4],[97,6],[125,8],[158,7]]]
};
const DESCRIPTIONS={add:['くりあがり なし','くりあがり あり','3けた・くりあがり あり'],sub:['くりさがり なし','くりさがり あり','3けた・0から くりさがり'],mul:['くくで ちょうせん','2けた × 1けた','2けた × 2けた'],div:['くくで われるよ','2けた ÷ 1けた','あまりの ある わりざん']};
const THEMES={animals:['どうぶつ','🐰'],sea:['うみ','🐬'],sweets:['おかし','🍰']};
const STICKERS=[['rabbit','🐰','うさぎ','animals'],['cat','🐱','ねこ','animals'],['bear','🐻','くま','animals'],['panda','🐼','パンダ','animals'],['dolphin','🐬','いるか','sea'],['fish','🐠','さかな','sea'],['octopus','🐙','たこ','sea'],['whale','🐳','くじら','sea'],['cake','🍰','ケーキ','sweets'],['donut','🍩','ドーナツ','sweets'],['ice','🍦','アイス','sweets'],['cookie','🍪','クッキー','sweets']];
const KEY='hissan-game-preview-v1';
let persistent=true;
function fresh(){return {owned:['rabbit','dolphin','cake'],placed:[],badges:[],rounds:0,bg:'cream',today:'',todayCount:0};}
function load(){try{const v=JSON.parse(localStorage.getItem(KEY));if(!v)return fresh();const ids=STICKERS.map(s=>s[0]);return {owned:Array.isArray(v.owned)?v.owned.filter(x=>ids.includes(x)):fresh().owned,placed:Array.isArray(v.placed)?v.placed.filter(p=>p&&ids.includes(p.id)&&[p.x,p.y,p.size,p.rot].every(Number.isFinite)).slice(0,100).map(p=>({...p,x:Math.max(12,Math.min(88,p.x)),y:Math.max(15,Math.min(85,p.y)),size:Math.max(52,Math.min(100,p.size)),rot:p.rot%360})):[],badges:Array.isArray(v.badges)?v.badges.filter(x=>OPS[x]):[],rounds:Number.isInteger(v.rounds)&&v.rounds>=0?v.rounds:0,bg:['cream','sea','pink'].includes(v.bg)?v.bg:'cream',today:typeof v.today==='string'?v.today:'',todayCount:Number.isInteger(v.todayCount)&&v.todayCount>=0?v.todayCount:0};}catch{persistent=false;return fresh();}}
let data=load(),config={op:'add',level:0,theme:'animals'},session=null,screen='setup',selectedStock=null,selectedPlaced=null,activeField='answer',noticeTimer;
function save(){try{localStorage.setItem(KEY,JSON.stringify(data));}catch{persistent=false;}storageNote();}
function storageNote(){if(!persistent&&!$('storage-note'))$('screen').insertAdjacentHTML('beforeend','<p class="storage-note" id="storage-note">このブラウザでは きろくを のこせないよ。ページを とじると シールは もとに もどるよ。</p>');}
function toast(t){$('notice').textContent=t;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('notice').textContent='',3000);}
function sticker(id){const s=STICKERS.find(x=>x[0]===id);return `<span class="sticker" role="img" aria-label="${s[2]}">${s[1]}</span>`;}
function today(){const d=new Date();return `${d.getFullYear()}-${d.getMonth()+1}-${d.getDate()}`;}
function updateNav(){ $('owned-count').textContent=data.owned.length;$('challenge-tab').setAttribute('aria-pressed',screen!=='album');$('album-tab').setAttribute('aria-pressed',screen==='album');}
function render(focus=true){updateNav();if(screen==='setup')setup();else if(screen==='quiz')quiz();else if(screen==='reward')reward();else album();storageNote();if(focus){$('screen').focus({preventScroll:true});window.scrollTo(0,0);}}
function setup(){const {op,level,theme}=config;const [a,b]=BANK[op][level][0];$('screen').innerHTML=`<section class="book"><div class="hero"><p class="eyebrow">TODAY'S LITTLE CHALLENGE</p><h1>きょうは なにを やってみる？</h1><p class="sub">すきな けいさんを 3もん。シールが 3まい もらえるよ。</p><img src="../assets/pencil-sticker.png" alt=""></div><div class="setup-grid"><section class="section"><h2><span class="number">1</span>けいさんを えらぼう</h2><div class="choices">${Object.entries(OPS).map(([k,v])=>`<button class="choice" data-op="${k}" aria-pressed="${k===op}"><b>${v[0]}</b>${v[1]}</button>`).join('')}</div></section><section class="section blue"><h2><span class="number">2</span>むずかしさは？</h2><div class="levels">${LEVELS.map((n,i)=>`<button data-level="${i}" aria-pressed="${i===level}">${n}</button>`).join('')}</div><p class="example">${DESCRIPTIONS[op][level]}<strong>たとえば ${a} ${OPS[op][0]} ${b}</strong></p></section></div><section class="section theme-section"><h2><span class="number">3</span>ほしい シールは？</h2><div class="themes">${Object.entries(THEMES).map(([k,v])=>`<button data-theme="${k}" aria-pressed="${k===theme}">${v[1]} ${v[0]}</button>`).join('')}</div></section><button class="primary start" id="start">3もんに ちょうせん！ →</button><p class="promise">🌼 ヒントを みても だいじょうぶ。さいごまで やってみよう。</p>${data.today===today()&&data.todayCount>=3?'<p class="badge">🌸 きょうの3もん できたね！ もっと あそんでも いいよ。</p>':''}</section>`;
document.querySelectorAll('[data-op]').forEach(b=>b.onclick=()=>{config.op=b.dataset.op;render(false);});document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{config.level=Number(b.dataset.level);render(false);});document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{config.theme=b.dataset.theme;render(false);});$('start').onclick=()=>{const pool=[...BANK[op][level]];for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}session={...config,questions:pool.slice(0,3).map(([a,b])=>({a,b,answer:'',remainder:'',done:false,hint:false})),index:0,claimed:false,rewards:[]};screen='quiz';render();};}
function solution(q){const op=session.op;return op==='add'?q.a+q.b:op==='sub'?q.a-q.b:op==='mul'?q.a*q.b:Math.floor(q.a/q.b);}
function quiz(){const q=session.questions[session.index],op=session.op,hasRemainder=op==='div'&&session.level===2;activeField='answer';$('screen').innerHTML=`<section class="book"><div class="row"><div><p class="eyebrow">きょうの3もん</p><h1>${OPS[op][0]} ${OPS[op][1]} <span class="sub">${LEVELS[session.level]}</span></h1></div><button id="leave">← えらびなおす</button></div><div class="progress" aria-label="${session.index+1}もんめ、ぜんぶで3もん">${session.questions.map((x,i)=>`<span class="${i===session.index?'now':x.done?'done':''}">${x.done?'✓ ':''}${i+1}もんめ</span>`).join('')}</div><div class="quiz-grid"><div><div class="problem"><p class="equation">${q.a} ${OPS[op][0]} ${q.b} ＝ ？</p>${op!=='div'?`<div class="vertical" aria-hidden="true"><span></span><span>${q.a}</span><span>${OPS[op][0]}</span><span>${q.b}</span><span class="rule">${q.done?solution(q):'？'}</span></div>`:'<p>わられる かずを<br>いくつずつに わけられるかな？</p>'}</div><button class="hint" id="hint" ${q.done?'disabled':''}>💡 ヒントを みる</button><div id="hint-box" ${q.hint?'':'hidden'} class="feedback">${hintText(q)}</div></div><div><div class="answer-fields"><label>こたえ<input id="answer" inputmode="numeric" pattern="[0-9]*" maxlength="5" autocomplete="off" value="${q.answer}" ${q.done?'disabled':''}></label>${hasRemainder?`<label>あまり<input id="remainder" inputmode="numeric" pattern="[0-9]*" maxlength="3" autocomplete="off" value="${q.remainder}" ${q.done?'disabled':''}></label>`:''}</div><div class="keypad" ${q.done?'hidden':''}>${['1','2','3','4','5','6','7','8','9','けす','0','ひとつけす'].map(n=>`<button data-key="${n}">${n}</button>`).join('')}</div><button class="primary check" id="check" ${q.done?'disabled':''}>${q.done?'✓ できた！':'こたえあわせ'}</button><p class="feedback ${q.done?'good':''}" id="feedback" role="status">${q.done?'できたね！ 「つぎへ」で すすもう。':'こたえを いれてみよう。'}</p></div></div><div class="controls"><button id="prev" ${session.index===0?'disabled':''}>← まえへ</button><button class="primary" id="next" ${q.done?'':'disabled'}>${session.index===2?'シールを もらう 🎁':'つぎへ →'}</button></div></section>`;
for(const id of ['answer','remainder'])if($(id)){ $(id).onfocus=()=>activeField=id;$(id).oninput=()=>{q[id]=$(id).value.replace(/[^0-9]/g,'').slice(0,id==='answer'?5:3);$(id).value=q[id];};$(id).onkeydown=e=>{if(e.key==='Enter'&&!q.done)checkAnswer();};}
document.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>{const input=$(activeField);if(q.done||!input)return;const k=b.dataset.key;q[activeField]=k==='けす'?'':k==='ひとつけす'?q[activeField].slice(0,-1):(q[activeField]+k).slice(0,activeField==='answer'?5:3);input.value=q[activeField];});$('check').onclick=checkAnswer;$('hint').onclick=()=>{q.hint=true;$('hint-box').hidden=false;};$('prev').onclick=()=>{session.index--;render();};$('next').onclick=()=>{if(!q.done)return;if(session.index<2){session.index++;render();}else{claim();screen='reward';render();}};$('leave').onclick=()=>{screen='setup';render();};}
function hintText(q){const op=session.op;if(op==='div')return `${q.b} × □ が ${q.a}を こえないように かんがえよう。<br>こたえは ${solution(q)}${session.level===2?'、あまり '+q.a%q.b:''}。たしかめて いれてみよう。`;return `${op==='mul'?'いちのくらいから かけてみよう。':'いちのくらいから けいさんしてみよう。'}<br>${q.a} ${OPS[op][0]} ${q.b} ＝ ${solution(q)}。たしかめて いれてみよう。`;}
function checkAnswer(){const q=session.questions[session.index];if(q.done)return;const rem=session.op==='div'&&session.level===2;if(q.answer===''||(rem&&q.remainder==='')){$('feedback').textContent=rem?'こたえと あまりを いれてね。':'こたえを いれてね。';return;}if(Number(q.answer)===solution(q)&&(!rem||Number(q.remainder)===q.a%q.b)){q.done=true;render(false);}else{$('feedback').textContent='おしい！ もういちど やってみよう。ヒントも みられるよ。';}}
function claim(){if(session.claimed||!session.questions.every(q=>q.done))return;session.claimed=true;const pool=STICKERS.filter(s=>s[3]===session.theme);const missing=pool.filter(s=>!data.owned.includes(s[0]));const ordered=[...missing,...pool.filter(s=>data.owned.includes(s[0]))];session.rewards=Array.from({length:3},(_,i)=>ordered[i%ordered.length][0]);data.owned.push(...session.rewards);data.rounds++;if(data.today!==today()){data.today=today();data.todayCount=0;}data.todayCount+=3;if(!data.badges.includes(session.op))data.badges.push(session.op);save();}
function reward(){ $('screen').innerHTML=`<section class="book reward"><p class="flower">🌸</p><p class="eyebrow">きょうの3もん できあがり！</p><h1>さいごまで できたね！</h1><p class="sub">${THEMES[session.theme][0]}の シールを 3まい プレゼント。</p><div class="reward-list">${session.rewards.map(id=>`<div class="sticker-wrap">${sticker(id)}<p>${STICKERS.find(s=>s[0]===id)[2]}</p></div>`).join('')}</div><p class="badge">🏅 ${OPS[session.op][1]}に ちょうせん！ バッジ</p><p class="sub">シールちょうに はって あそぼう。</p><div class="controls"><button id="again">もう3もん あそぶ</button><button class="primary" id="open-album">シールを はる →</button></div></section>`;$('again').onclick=()=>{session=null;screen='setup';render();};$('open-album').onclick=()=>{screen='album';render();};}
function album(){const unique=new Set(data.owned);$('screen').innerHTML=`<section class="book"><p class="eyebrow">MY LITTLE STICKER BOOK</p><div class="row"><h1>わたしの シールちょう</h1><span class="collection-summary">${unique.size} / ${STICKERS.length}しゅるい ・ ${data.owned.length}まい</span></div><p class="sub">シールを えらんで、ノートの すきな ばしょを おしてね。</p><div class="album-grid"><aside class="inventory"><h2>あつめた シール</h2><p class="muted">はじめの プレゼントは 3まい！<br>はった シールは また つかえるよ。</p><div class="sticker-grid">${STICKERS.map(s=>{const n=data.owned.filter(x=>x===s[0]).length;return n?`<button class="stock" data-stock="${s[0]}" aria-label="${s[2]} ${n}まい" aria-pressed="${selectedStock===s[0]}">${sticker(s[0])}<small>${n}まい</small></button>`:`<div class="stock locked" aria-label="${s[2]} まだ もっていない"><span>？</span><small>まだだよ</small></div>`;}).join('')}</div></aside><div><div class="board-tools"><label>ノートの いろ <select id="bg"><option value="cream">クリーム</option><option value="sea">みずいろ</option><option value="pink">ピンク</option></select></label></div><div class="board" id="board" data-bg="${data.bg}" aria-label="シールを はる ノート"><span class="board-label">${data.placed.length?'わたしだけの たからもの':'ここに シールを はってみよう ♡'}</span>${data.placed.map((p,i)=>`<button class="placed" data-placed="${i}" aria-pressed="${selectedPlaced===i}" aria-label="${STICKERS.find(s=>s[0]===p.id)[2]} はったシール ${i+1}" style="left:${p.x}%;top:${p.y}%;--rot:${p.rot}deg;--size:${p.size}px">${sticker(p.id)}</button>`).join('')}</div><div class="board-tools"><button id="place-center" ${selectedStock?'':'disabled'}>まんなかに はる</button><button id="bigger" ${selectedPlaced!==null?'':'disabled'}>おおきさ</button><button id="rotate" ${selectedPlaced!==null?'':'disabled'}>まわす ↻</button><button id="remove" ${selectedPlaced!==null?'':'disabled'}>はがす</button></div><p class="muted" id="album-help" role="status">${selectedStock?STICKERS.find(s=>s[0]===selectedStock)[2]+'を えらんだよ。すきな ばしょを おしてね。':selectedPlaced!==null?'えらんだ シールを うごかすには、ノートを おしてね。':'はった シールを おすと、おおきさや むきを かえられるよ。'}</p></div></div><div class="badge">🏅 できた！ コレクション<br>${data.badges.length?data.badges.map(op=>OPS[op][1]+'に ちょうせん').join(' ・ '):'3もんに ちょうせんすると バッジが ふえるよ。'}</div><p class="muted">このブラウザに シールと ノートが のこるよ。</p></section>`;
$('bg').value=data.bg;$('bg').onchange=()=>{data.bg=$('bg').value;$('board').dataset.bg=data.bg;save();};document.querySelectorAll('[data-stock]').forEach(b=>b.onclick=()=>{selectedStock=b.dataset.stock;selectedPlaced=null;render(false);});document.querySelectorAll('[data-placed]').forEach(b=>b.onclick=e=>{e.stopPropagation();selectedPlaced=Number(b.dataset.placed);selectedStock=null;render(false);});
$('board').onclick=e=>{const r=$('board').getBoundingClientRect();place((e.clientX-r.left)/r.width*100,(e.clientY-r.top)/r.height*100);};$('place-center').onclick=()=>place(50,50);
$('board').onkeydown=e=>{if(selectedPlaced===null||!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const p=data.placed[selectedPlaced];p.x=Math.max(12,Math.min(88,p.x+(e.key==='ArrowRight'?3:e.key==='ArrowLeft'?-3:0)));p.y=Math.max(15,Math.min(85,p.y+(e.key==='ArrowDown'?3:e.key==='ArrowUp'?-3:0)));save();const i=selectedPlaced;render(false);document.querySelector(`[data-placed="${i}"]`).focus();};
$('bigger').onclick=()=>editPlaced(p=>p.size=p.size===76?100:p.size===100?52:76);$('rotate').onclick=()=>editPlaced(p=>p.rot=(p.rot+20)%360);$('remove').onclick=()=>{if(selectedPlaced===null)return;data.placed.splice(selectedPlaced,1);selectedPlaced=null;save();render(false);toast('シールを はがしたよ。また はれるよ。');};}
function place(x,y){if(selectedStock){if(data.placed.length>=100){toast('ノートが いっぱいだよ。すこし はがしてね。');return;}data.placed.push({id:selectedStock,x:Math.max(12,Math.min(88,x)),y:Math.max(15,Math.min(85,y)),size:76,rot:-8});}else if(selectedPlaced!==null){data.placed[selectedPlaced].x=Math.max(12,Math.min(88,x));data.placed[selectedPlaced].y=Math.max(15,Math.min(85,y));}else{toast('はじめに シールを えらんでね。');return;}save();render(false);}
function editPlaced(fn){if(selectedPlaced===null)return;fn(data.placed[selectedPlaced]);save();render(false);}
$('challenge-tab').onclick=()=>{screen=session?(session.claimed?'reward':'quiz'):'setup';render();};$('album-tab').onclick=()=>{screen='album';render();};render(false);
